class InboxScreen extends StatefulWidget {
  const InboxScreen({super.key,required this.api,required this.user,required this.themeMode,required this.onCycleTheme,required this.onLogout});
  final ApiClient api; final SupportUser user; final ThemeMode themeMode; final VoidCallback onCycleTheme; final Future<void> Function() onLogout;
  @override State<InboxScreen> createState()=>_InboxScreenState();
}
class _InboxScreenState extends State<InboxScreen> with WidgetsBindingObserver{
  final _search=TextEditingController(); StreamSubscription<Map<String,dynamic>>? _events; Timer? _debounce; List<SupportTicket> _tickets=const[]; bool _loading=true; String? _error; String _filter='Open';
  @override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);_refresh();_events=widget.api.supportEvents().listen((e){if(e['type']=='keepalive'||e['type']=='connected')return;_debounce?.cancel();_debounce=Timer(const Duration(milliseconds:250),()=>_refresh(silent:true));});}
  @override void dispose(){WidgetsBinding.instance.removeObserver(this);_search.dispose();_events?.cancel();_debounce?.cancel();super.dispose();}
  @override void didChangeAppLifecycleState(AppLifecycleState s){if(s==AppLifecycleState.resumed)_refresh(silent:true);}
  Future<void> _refresh({bool silent=false}) async {if(!silent&&mounted)setState(()=>_loading=true);try{final items=await widget.api.loadTickets();if(mounted)setState((){_tickets=items;_error=null;});}on ApiException catch(e){if(mounted)setState(()=>_error=e.message);}catch(_){if(mounted)setState(()=>_error='Could not refresh support inbox.');}finally{if(mounted)setState(()=>_loading=false);}}
  List<SupportTicket> get visible{final q=_search.text.trim().toLowerCase();return _tickets.where((t){final f=switch(_filter){'Mine'=>t.assignedTo?.toLowerCase()==widget.user.email.toLowerCase(),'Unassigned'=>t.assignedTo==null||t.assignedTo!.isEmpty,'Open'=>t.isOpen,'Resolved'=>t.status=='RESOLVED'||t.status=='CLOSED',_=>true};if(!f)return false;if(q.isEmpty)return true;return [t.reference,t.subject,t.openedBy??'',t.email??'',t.phoneNumber??'',t.tenantName??''].join(' ').toLowerCase().contains(q);}).toList();}
  Future<void> _open(SupportTicket t) async {await Navigator.of(context).push(MaterialPageRoute(builder:(_)=>ConversationScreen(api:widget.api,user:widget.user,initialTicket:t)));await _refresh(silent:true);}
  String _initials(String v){final p=v.trim().split(RegExp(r'\s+')).where((e)=>e.isNotEmpty).take(2);return p.isEmpty?'AS':p.map((e)=>e[0].toUpperCase()).join();}
  @override Widget build(BuildContext context){final c=Theme.of(context).colorScheme,items=visible;return Scaffold(appBar:AppBar(titleSpacing:16,title:Row(children:[ClipRRect(borderRadius:BorderRadius.circular(9),child:Image.asset('assets/arofi_app_icon.png',width:34,height:34)),const SizedBox(width:10),const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('AroFi Support',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),Text('Live agent inbox',style:TextStyle(fontSize:10.5))])]),actions:[IconButton(tooltip:'Theme: ${widget.themeMode.name}',onPressed:widget.onCycleTheme,icon:Icon(switch(widget.themeMode){ThemeMode.light=>Icons.light_mode_outlined,ThemeMode.dark=>Icons.dark_mode_outlined,ThemeMode.system=>Icons.brightness_auto_outlined})),PopupMenuButton<String>(onSelected:(v){if(v=='logout')widget.onLogout();},itemBuilder:(_)=>[PopupMenuItem(enabled:false,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.user.displayName,style:const TextStyle(fontWeight:FontWeight.w700)),Text(widget.user.email,style:const TextStyle(fontSize:11))])),const PopupMenuDivider(),const PopupMenuItem(value:'logout',child:ListTile(leading:Icon(Icons.logout),title:Text('Sign out')))],child:Padding(padding:const EdgeInsets.only(right:14),child:CircleAvatar(radius:17,backgroundColor:c.primaryContainer,child:Text(_initials(widget.user.displayName),style:TextStyle(color:c.onPrimaryContainer,fontSize:11,fontWeight:FontWeight.w800))))) ]),body:RefreshIndicator(onRefresh:_refresh,child:CustomScrollView(physics:const AlwaysScrollableScrollPhysics(),slivers:[SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[TextField(controller:_search,onChanged:(_)=>setState((){}),decoration:InputDecoration(hintText:'Search name, phone, email or ticket…',prefixIcon:const Icon(Icons.search),suffixIcon:_search.text.isEmpty?null:IconButton(onPressed:(){_search.clear();setState((){});},icon:const Icon(Icons.close)))),const SizedBox(height:10),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['Open','Mine','Unassigned','All','Resolved'].map((x)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(x),selected:_filter==x,onSelected:(_)=>setState(()=>_filter=x)))).toList()))]))),if(_error!=null)SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.symmetric(horizontal:14),child:Text(_error!,style:TextStyle(color:c.error)))),if(_loading&&_tickets.isEmpty)const SliverFillRemaining(child:Center(child:CircularProgressIndicator()))else if(items.isEmpty)const SliverFillRemaining(hasScrollBody:false,child:Center(child:Text('No conversations here')))else SliverPadding(padding:const EdgeInsets.fromLTRB(14,0,14,24),sliver:SliverList.separated(itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i)=>_TicketCard(ticket:items[i],currentEmail:widget.user.email,onTap:()=>_open(items[i]))))])),floatingActionButton:FloatingActionButton.small(onPressed:_refresh,child:const Icon(Icons.refresh)));}
}
class _TicketCard extends StatelessWidget{const _TicketCard({required this.ticket,required this.currentEmail,required this.onTap});final SupportTicket ticket;final String currentEmail;final VoidCallback onTap;@override Widget build(BuildContext context){final last=ticket.lastMessage,mine=ticket.assignedTo?.toLowerCase()==currentEmail.toLowerCase(),un=ticket.assignedTo==null||ticket.assignedTo!.isEmpty;return Card(child:InkWell(borderRadius:BorderRadius.circular(14),onTap:onTap,child:Padding(padding:const EdgeInsets.all(14),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[CircleAvatar(child:Icon(ticket.isLiveChat?Icons.forum_outlined:Icons.support_agent)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(ticket.openedBy?.isNotEmpty==true?ticket.openedBy!:ticket.subject,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w800,fontSize:15))),Text(_time(ticket.sortTime),style:const TextStyle(fontSize:10.5))]),const SizedBox(height:3),Text(ticket.subject,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:12.5,fontWeight:FontWeight.w600)),if(last!=null)...[const SizedBox(height:4),Text(last.body,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:12))],const SizedBox(height:8),Wrap(spacing:6,children:[_Badge(ticket.isLiveChat?'LIVE CHAT':ticket.channel,const Color(0xFF22A53A)),_Badge(ticket.status.replaceAll('_',' '),const Color(0xFF64748B)),if(mine)_Badge('MINE',const Color(0xFF2563EB)),if(un)_Badge('UNASSIGNED',const Color(0xFFD97706))])])),const Icon(Icons.chevron_right)])))));}
  String _time(DateTime t){final d=DateTime.now().difference(t.toLocal());if(d.inMinutes<1)return'now';if(d.inMinutes<60)return'${d.inMinutes}m';if(d.inHours<24)return'${d.inHours}h';if(d.inDays<7)return'${d.inDays}d';return DateFormat('dd MMM').format(t.toLocal());}}
class _Badge extends StatelessWidget{const _Badge(this.label,this.color);final String label;final Color color;@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:7,vertical:3),decoration:BoxDecoration(color:color.withValues(alpha:.09),borderRadius:BorderRadius.circular(999)),child:Text(label,style:TextStyle(color:color,fontSize:9,fontWeight:FontWeight.w800)));}
